import{_ as t,c as a,o as n,ag as r}from"./chunks/framework.Vyheyqg9.js";const g=JSON.parse('{"title":"AI for Software Development","description":"","frontmatter":{},"headers":[],"relativePath":"ai-assisted-engineering/index.md","filePath":"ai-assisted-engineering/index.md"}'),i={name:"ai-assisted-engineering/index.md"};function o(s,e,d,l,h,c){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-for-software-development" tabindex="-1">AI for Software Development <a class="header-anchor" href="#ai-for-software-development" aria-label="Permalink to “AI for Software Development”">​</a></h1><p>Use an AI assistant to understand a repository, fix bugs, develop features, test changes and prepare a reviewable PR handoff. You remain responsible for the requirements, code and evidence. No AI-development or Python knowledge is required to begin; use a small JavaScript/TypeScript repository you understand.</p><p>Want to <strong>build chatbots, RAG, workflows and MCP servers</strong>? Follow <a href="./../applied-ai/">Build AI Apps — JavaScript First</a>. That path teaches the product you build; this path teaches how to work on software with AI. You can study them together.</p><h2 id="begin-with-a-concrete-task" tabindex="-1"><span class="hub-section-number">1 </span>Begin with a concrete task <a class="header-anchor" href="#begin-with-a-concrete-task" aria-label="Permalink to “1 Begin with a concrete task”">​</a></h2><p>Start with <a href="./getting-started.html">getting started</a>, then the <a href="./bug-fixing.html">catalogue mutation bug</a>. The continuing project is a tiny TypeScript notes catalogue, separate from the chatbot&#39;s UI. You will reproduce a defect, fix it, then add a query/limit feature. Its <a href="./../workbench/engineering/ai-engineering/catalogue/">worked source</a> is a reference to inspect after making your own prediction.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Lesson</th><th>Observable result</th></tr></thead><tbody><tr><td>1</td><td><a href="./getting-started.html">Getting started with a coding assistant</a></td><td>A precise task, repository context and an inspected proposed change</td></tr><tr><td>2</td><td><a href="./bug-fixing.html">Fix a bug</a></td><td>Reproducer fails before the correction and passes afterward</td></tr><tr><td>3</td><td><a href="./feature-development.html">Develop a feature</a></td><td>Acceptance criteria map to a focused implementation and checks</td></tr><tr><td>4</td><td><a href="./testing-debugging.html">Test and debug</a></td><td>Classify failures and challenge generated tests with a meaningful defect</td></tr><tr><td>5</td><td><a href="./review-pr.html">Review and prepare a PR</a></td><td>Actual diff review and factual local handoff</td></tr><tr><td>6</td><td><a href="./reusable-tools.html">Reusable workflows and tools</a></td><td>A runbook, scoped context and a reasoned tool choice</td></tr><tr><td>7</td><td><a href="./advanced-coordination.html">Advanced coordination</a></td><td>Explain when worktrees or multiple agents help and how to reconcile results</td></tr></tbody></table><p>Use the <a href="./../practice/engineering/ai-engineering/development-project.html">independent development projects</a>. All learner practice remains outstanding. The reference&#39;s passing checks do not establish your own independent capability or a separate human review.</p><h2 id="retain-the-existing-engineering-depth" tabindex="-1"><span class="hub-section-number">2 </span>Retain the existing engineering depth <a class="header-anchor" href="#retain-the-existing-engineering-depth" aria-label="Permalink to “2 Retain the existing engineering depth”">​</a></h2><p>The previous four lessons remain unchanged and available for the next layer:</p><ul><li><a href="./issue-to-reviewed-change.html">Issue to a reviewed local change</a>: detailed retry-bug investigation and contract analysis.</li><li><a href="./verification-and-permissions.html">Verification and permissions</a>: evidence, API checks and defect challenges.</li><li><a href="./local-workflow-and-git.html">Local workflow and Git</a>: repeatable stages, worktrees and safe local handoffs.</li><li><a href="./traceability-and-evaluation.html">Traceability and evaluation</a>: requirement mapping and measured outcomes.</li></ul><p>This repository forbids remote pushes. Prepare changes and PR text locally; only the user may push. Do not claim a PR, CI result or independent review exists unless it actually does.</p>',11)])])}const f=t(i,[["render",o]]);export{g as __pageData,f as default};
